function readSaved(){try{const saved=JSON.parse(localStorage.getItem('palacete-shortlist')||'[]');return Array.isArray(saved)?saved:[]}catch{return[]}}function writeSaved(items){try{localStorage.setItem('palacete-shortlist',JSON.stringify(items))}catch{}}
let filter='all',toastTimer;const toast=document.querySelector('#toast');function update(){const saved=readSaved();document.querySelector('#count').textContent=saved.length;document.querySelectorAll('.save-design').forEach(b=>{const on=saved.includes(b.dataset.id);b.setAttribute('aria-pressed',String(on));b.textContent=on?'♥':'♡'});let shown=0;document.querySelectorAll('.design-card').forEach(c=>{c.hidden=filter==='saved'&&!saved.includes(c.dataset.id);if(!c.hidden)shown++});document.querySelector('#empty').hidden=shown>0;document.querySelectorAll('[data-show]').forEach(b=>b.classList.toggle('active',b.dataset.show===filter))}document.querySelectorAll('.save-design').forEach(b=>b.addEventListener('click',()=>{const saved=readSaved(),on=saved.includes(b.dataset.id);writeSaved(on?saved.filter(x=>x!==b.dataset.id):[...saved,b.dataset.id]);update();toast.textContent=on?'Removed from your shortlist':'Added to your shortlist on this browser';toast.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('visible'),2200)}));document.querySelectorAll('[data-show]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.show;update()}));document.querySelector('#shortlist-view').addEventListener('click',()=>{filter='saved';update();document.querySelector('#collection').scrollIntoView()});addEventListener('storage',update);addEventListener('pageshow',update);update();
